def basis_for(rule_id):
    if str(rule_id)=='31':
        resource=json.loads((Path(__file__).parent/'resources/gbt7714-2025-verified.json').read_text())
        clauses=[
            ('general',[9,10,11,14], '参考文献著录题名必备；文献类型标识按附录A必备。电子资源还必备载体标识。作者、其他题名信息及多数出版信息为有则必备，不能无条件要求存在；顺序编码制无责任者的文献可省略作者。第1版可不著录，其他版本说明有则著录。末尾句点可用，不是必用。'),
            ('A',[34,35], '文献类型代码：M图书，J期刊，N报纸，C会议录，D学位论文，R报告，S标准，P专利，EB网站/网页，A档案，CM地图，DS数据集，PP预印本，G汇编，CP计算机程序，DB数据库，Z其他。载体代码MT磁带、DK磁盘、CD光盘、OL联机网络、MM缩微资料。类型和载体标识置于方括号内，载体前用/。'),
            ('7.5-7.9',[12,13,14], '出版信息次序为出版地、出版者、出版日期。出版地/出版者不明可用方括号中的不详说明；无出版地/出版者的电子资源可省略。出版年采用阿拉伯数字公元纪年；无法确定可采用版权年、印刷年、方括号中的估计年。创建、发布、修改、引用日期按YYYY-MM-DD著录。页码可使用文章编号。电子资源获取路径据实际情况著录；DOI等永久标识符为可选，URL已含永久标识符可不重复，不得把DOI或URL当所有文献通用必填。'),
            ('8.2-8.5',[14,15,16,17,18], '图书及连续出版物的题名、类型标识必备；只有当被引资源是电子资源时，才要求载体和获取路径必备。主要责任者、出版地、出版者、出版年、版本、页码等有则必备；图书析出文献的析出题名与图书题名必备，出处前用//。期刊析出文献的题名、类型标识必备；期刊名、年卷期页码有则必备，不能把期/卷/页码一概判必填。期刊格式为作者.题名[类型/载体].刊名,年,卷(期):页码.路径.永久标识符。年置于作者后是著者-出版年制的允许差异。'),
            ('8.6',[19,20], '一般会议录题名、类型标识必备，只有当被引资源是电子资源时，才要求载体和路径必备；责任者、会议名、会议年份、页码有则必备。会议录若以图书、图书析出、连续出版物及其析出形式出现，应按相应形式著录。一般形式为作者.题名[类型/载体]//会议名,会议年份:页码.路径.永久标识符。'),
            ('8.7',[21], '学位论文题名、类型标识、学位授予单位必备；只有当被引资源是电子资源时，才要求载体和路径必备。作者、单位所在地、授予年份和引文页码有则必备。格式为作者.题名[D/载体].所在地:学位授予单位,年份:页码.路径.永久标识符。'),
            ('8.8-8.9',[22,23], '报告题名、类型标识必备；只有当被引资源是电子资源时，才要求载体和路径必备；作者、报告编号、发布日期、页码有则必备。当被引资源是标准时，其标准编号、标准名称及类型标识S必备；此处S仅表示被引的标准，不表示被引的学位论文（学位论文类型为D）；只有当被引资源是电子资源时，才要求载体和路径必备。标准按标准编号 标准名称[S/载体].路径.永久标识符著录，不要额外强制作者出版地出版社。'),
            ('8.10',[23,24], '专利的申请者或所有者、题名、专利申请号、类型标识必备；只有当被引资源是电子资源时，才要求载体和路径必备；公告或公开日期、页码有则必备。'),
            ('8.11',[24,25], '一般网站、网页：题名、类型标识、载体标识、引用日期、获取和访问路径必备；作者、创建或修改日期有则必备；永久标识符可选。以网页形式出现的图书、期刊、论文、会议录、报告、标准、专利等按其相应文献类型处理，不能只因有URL就强制套用一般网页规则。'),
            ('8.12-8.13',[26,27], '一般档案题名、类型标识必备；只有当被引资源是电子资源时，才要求载体和路径必备；作者、档号、收藏地、收藏者、形成日期、页码有则必备。一般地图题名、类型标识必备；只有当被引资源是电子资源时，才要求载体和路径必备；纸质单幅地图尺寸必备；作者、比例尺、版本、出版地、出版者、出版年有则必备。图书或图书析出形式的档案/地图按相应形式处理。'),
            ('8.14-8.15',[28,29], '一般数据集和预印本题名、类型标识、引用日期必备；数据集电子资源载体及路径必备，预印本路径必备且电子资源载体必备；主要责任者、创建或发布或修改日期有则必备。数据集版本可选；预印本版本有则必备。发布/出版平台和永久标识符可选。若以图书、期刊等形式出现，按相应形式处理。'),
            ('9.1-9.2',[29,30,31], '允许顺序编码制或著者-出版年制。顺序编码制按正文首次引用先后连续编号，序号放在[]内；脚注自动编号允许圈码。同处多引的各编号用逗号，连续序号用短横线；自动编号有例外，不能据PDF缺少生成信息直接否定例外。重复引用沿用首次编号，页码置于方括号外；自动脚注可重复著录及简写。参考文献表按文内编号依次排列。'),
            ('9.3',[31,32], '著者-出版年制正文引用用(责任者姓氏,出版年)；正文已提及责任者时可仅(年份)。多作者欧美使用首作者姓氏 et al.，中国作者使用首作者姓名 等。同一作者同年多文献用年份后小写字母区分。重复引用的页码置于括号外。文献表按文种、作者字顺、出版年排列，中文可按拼音或笔画笔顺。')]
        return [{'id':'gbt7714-2025:'+ident,'pdf_pages':pages,'text':text,'source_sha256':resource['source_sha256'],'review':'transcribed normative summary checked against supplied page images'} for ident,pages,text in clauses] + [
            {'id':'phase1-interpretation','text':'本项目为学位论文。缺字段必须区分原文确认未著录与抽取失败。有则必备字段只有外部作品元数据已证实存在该字段时才可判断漏录。语义歧义和缺少自动编号/原作品信息必须保留UNKNOWN。'}]
    if str(rule_id)=='32':return [{'id':'phase1-existence','text':'引用不存在指文后条目对应的外部作品不存在，区别于第22条本地参考文献条目缺失。存在性需标题、作者、年份、标识符等联合消歧。错误DOI但真实作品可通过其他证据确认存在，不判不存在。未检索到、接口失败、覆盖不足均为UNKNOWN。只有独立且范围完整的排除证据才能确证不存在。'}]
    if str(rule_id)=='33':return [{'id':'phase1-relevance','text':'按具体ReferenceUse的引用目的与已确认ExternalWork的内容判断相关性。方法借鉴、背景、定义、数据、比较、批评及反驳都可能相关；跨学科和结论不同不等于无关。同处多引逐条判断贡献。正文局部原句与被引内容均须有可追溯证据；只有摘要缺细节、题名不同、全文不可达不能判无关。证据不足按固定策略补查后保留UNKNOWN。'}]
    raise ValueError('unknown initial rule')
